def api_transport(
    requests: list[httpx.Request], failure: str = ""
) -> httpx.MockTransport:
    """Emulate the existing app endpoints and inject specific failure modes."""
    queries = 0

    def handle(request: httpx.Request) -> httpx.Response:
        """Check request isolation and return API-shaped evidence."""
        nonlocal queries
        requests.append(request)
        path = request.url.path
        if path == "/health/ready":
            return httpx.Response(200, json={"ready": failure != "unready"})
        if path == "/collections" and request.method == "GET":
            records = [{"id": "default", "name": "Default"}]
            if failure == "duplicate":
                records.append({"id": "existing", "name": "squad-eval"})
            return httpx.Response(200, json={"collections": records})
        if path == "/admin/config":
            return httpx.Response(
                200, json={"llm": {"model": "local"}, "retrieval": {}}
            )
        if path == "/collections":
            assert request.method == "POST"
            assert json.loads(request.content)["name"] == "squad-eval"
            return httpx.Response(200, json={"id": "isolated"})
        if path == "/documents/upload":
            assert b'name="collection_id"\r\n\r\nisolated' in request.content
            assert b"The launch code is Amber." in request.content
            assert b"Question answer?" not in request.content
            if failure == "upload":
                return httpx.Response(500, json={"detail": "ingestion failed"})
            return httpx.Response(
                200,
                json={
                    "status": "ok",
                    "document_id": "doc-1",
                    "collection_id": "isolated",
                    "chunks": 1,
                    "indexed": (
                        0
                        if failure == "partial-upload"
                        else True
                        if failure == "invalid-indexed"
                        else 1
                    ),
                },
            )
        if path == "/query":
            body = json.loads(request.content)
            assert body["use_cache"] is False
            assert body["stream"] is False
            assert body["collection_id"] == "isolated"
            assert body["query"] != "Question excluded?"
            queries += 1
            if failure == "query" and queries == 1:
                return httpx.Response(500, json={"detail": "generation failed"})
            if failure == "timeout" and queries == 1:
                raise httpx.ReadTimeout("query timed out", request=request)
            doc = "another-user-doc" if failure == "scope" else "doc-1"
            result = {
                "answer": "Amber",
                "cached": failure == "cached",
                "sources": [
                    {
                        "index": 1,
                        "document_id": doc,
                        "chunk_id": "doc-1:0",
                        "preview": "short",
                    }
                ],
                "retrieval_chunks": [
                    {
                        "document_id": doc,
                        "chunk_id": "doc-1:0",
                        "text": "The launch code is Amber.",
                    }
                ],
            }
            if failure == "missing-context":
                result.pop("retrieval_chunks")
            elif failure == "duplicate-chunks":
                result["retrieval_chunks"] *= 2
            return httpx.Response(200, json=result)
        raise AssertionError(f"Unexpected endpoint: {request.method} {path}")

    return httpx.MockTransport(handle)


def test_baseline_success(dataset: Path, tmp_path: Path) -> None:
    """Upload only corpus and preserve full selected contexts and run provenance."""
    requests: list[httpx.Request] = []
    output = tmp_path / "results"
    with httpx.Client(
        base_url="http://127.0.0.1:8000", transport=api_transport(requests)
    ) as client:
        state = run_baseline(dataset, output, client)
    assert state["status"] == "completed"
    assert state["completed"] == 2 and state["failed"] == 0
    assert len(state["documents"]) == 1
    assert state["config"]["llm"]["model"] == "local"
    rows = [
        json.loads(line) for line in (output / "results.jsonl").read_text().splitlines()
    ]
    assert [row["case"]["id"] for row in rows] == ["answer", "challenge"]
    assert all(row["duration_ms"] >= 0 for row in rows)
    assert (
        rows[0]["response"]["prompt_contexts"][0]["text"] == "The launch code is Amber."
    )
    assert rows[0]["response"]["prompt_contexts"][0]["passage_id"] in state["documents"]
    assert not any(request.method in {"DELETE", "PATCH"} for request in requests)
    with httpx.Client(
        base_url="http://127.0.0.1:8000", transport=api_transport(requests)
    ) as client:
        count = len(requests)
        with pytest.raises(FileExistsError):
            run_baseline(dataset, output, client)
        assert len(requests) == count


