@pytest.mark.parametrize(
    "damage",
    [
        "hash",
        "review",
        "traversal",
        "corpus",
        "missing",
        "unknown",
        "bad-id",
        "bad-decision",
    ],
)
def test_invalid_dataset(dataset: Path, damage: str) -> None:
    """Reject stale decisions and changed evidence before contacting the backend."""
    manifest = json.loads((dataset / "manifest.json").read_text())
    review = json.loads((dataset / "review.json").read_text())
    if damage == "hash":
        review["cases_sha256"] = "stale"
    elif damage == "review":
        review["cases"].pop()
    elif damage == "unknown":
        review["cases"][0]["id"] = "unknown"
    elif damage == "traversal":
        manifest["passages"][0]["file"] = "../cases.jsonl"
    elif damage == "missing":
        manifest["question_ids"].pop()
    elif damage == "bad-id":
        manifest["question_ids"][0] = []
    elif damage == "bad-decision":
        review["cases"][0]["decision"] = []
    else:
        next((dataset / "corpus").glob("*.md")).write_text("changed")
    save_json(dataset / "review.json", review)
    save_json(dataset / "manifest.json", manifest)
    with pytest.raises(ValueError):
        load_dataset(dataset)


