@pytest.mark.parametrize("failed", [0, 1])
def test_cli_query_exit_status(monkeypatch: pytest.MonkeyPatch, failed: int) -> None:
    """Make incomplete evaluations fail the CLI even when the runner returns."""

    def run(dataset: Path, output: Path, client: httpx.Client, name: str) -> dict:
        """Return a journal summary without network requests."""
        assert name == "squad-eval"
        assert str(client.base_url) == "http://127.0.0.1:8000"
        return {"completed": 2 - failed, "failed": failed}

    monkeypatch.setattr(
        sys, "argv", ["baseline", "--dataset", "missing", "--output", "unused"]
    )
    monkeypatch.setattr(runner, "run_baseline", run)
    if failed:
        with pytest.raises(SystemExit) as error:
            runner.main()
        assert error.value.code == 1
